#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <utility>
using namespace std;

typedef pair<int,int> pii;
const int N = 11;
const int INF = 1e9;
const int MAXV = 2 * N * N + 5;

struct Edge {
    int to, c, f, rev;
    Edge() {}
    Edge(int to_, int c_, int f_, int rev_): to(to_), c(c_), f(f_), rev(rev_) {}
};

struct Dinic {
    vector<Edge> g[MAXV];
    int d[MAXV], ptr[MAXV];

    void addEdge(int v, int u, int cap) {
        g[v].push_back(Edge(u, cap, 0, 0));
        g[u].push_back(Edge(v, 0, 0, 0));
        g[v].back().rev = (int)g[u].size() - 1;
        g[u].back().rev = (int)g[v].size() - 1;
    }

    bool buildLevel(int s, int t) {
        for (int i = 0; i <= t; ++i) d[i] = INF;
        queue<int> q;
        d[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (size_t i = 0; i < g[v].size(); ++i) {
                const Edge &e = g[v][i];
                if (d[e.to] == INF && e.c > e.f) {
                    d[e.to] = d[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return d[t] != INF;
    }

    int dfs(int v, int t, int curFlow) {
        if (v == t) return curFlow;
        for (int &i = ptr[v]; i < (int)g[v].size(); ++i) {
            Edge &e = g[v][i];
            int cf = e.c - e.f;
            if (d[e.to] == d[v] + 1 && cf > 0) {
                int add = dfs(e.to, t, min(curFlow, cf));
                if (add) {
                    e.f += add;
                    g[e.to][e.rev].f -= add;
                    return add;
                }
            }
        }
        return 0;
    }

    int maxflow(int s, int t) {
        int flow = 0;
        while (buildLevel(s, t)) {
            memset(ptr, 0, sizeof(ptr));
            int add;
            while ((add = dfs(s, t, INF)) != 0) flow += add;
        }
        return flow;
    }
};

int n, tbad;
char a[N][N], b[N][N];
int badDist[N][N], curDist[N][N];
pii bad;
const int dx[4] = {-1, 1, 0, 0};
const int dy[4] = {0, 0, -1, 1};

bool ok(pii v) {
    return v.first >= 0 && v.first < n && v.second >= 0 && v.second < n &&
           a[v.first][v.second] != 'Y' && a[v.first][v.second] != 'Z';
}

void bfsGrid(int sx, int sy, int dist[N][N], bool isBadSource) {
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            dist[i][j] = INF;

    queue<pii> q;
    dist[sx][sy] = 0;
    q.push(make_pair(sx, sy));

    while (!q.empty()) {
        pii v = q.front(); q.pop();

        if (!isBadSource && dist[v.first][v.second] == badDist[v.first][v.second])
            continue;

        for (int k = 0; k < 4; ++k) {
            int nx = v.first + dx[k];
            int ny = v.second + dy[k];
            pii nv = make_pair(nx, ny);
            if (ok(nv) && dist[nx][ny] == INF &&
                dist[v.first][v.second] + 1 <= badDist[nx][ny]) {
                dist[nx][ny] = dist[v.first][v.second] + 1;
                q.push(nv);
            }
        }
    }
}

int main() {
    cin >> n >> tbad;

    int px = 0, py = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
            if (a[i][j] == 'Z') px = i, py = j;
        }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            cin >> b[i][j];

    bad = make_pair(px, py);
    bfsGrid(px, py, badDist, true);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            badDist[i][j] = min(badDist[i][j], tbad);

    Dinic din;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (a[i][j] != '0') din.addEdge(0, i * n + j + 1, a[i][j] - '0');
            if (b[i][j] != '0') din.addEdge(i * n + j + 1 + n * n, 2 * n * n + 1, b[i][j] - '0');
        }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (!ok(make_pair(i, j))) continue;
            bfsGrid(i, j, curDist, false);
            for (int i1 = 0; i1 < n; ++i1)
                for (int j1 = 0; j1 < n; ++j1)
                    if (ok(make_pair(i1, j1)) && curDist[i1][j1] <= badDist[i1][j1])
                        din.addEdge(i * n + j + 1, i1 * n + j1 + 1 + n * n, INF);
        }

    cout << din.maxflow(0, 2 * n * n + 1);
    return 0;
}
